solutions.naive:
class Solution:
    def makeGood(self, s: str) -> str:
        def bad(a, b):
            return a != b and a.lower() == b.lower()
        changed = True
        while changed:
            changed = False
            i = 0
            out = []
            while i < len(s):
                if i + 1 < len(s) and bad(s[i], s[i + 1]) and not changed:
                    i += 2
                    changed = True
                else:
                    out.append(s[i])
                    i += 1
            s = ''.join(out)
        return s

solutions.better:
class Solution:
    def makeGood(self, s: str) -> str:
        stack = []
        for ch in s:
            if stack and stack[-1] != ch and stack[-1].lower() == ch.lower():
                stack.pop()
            else:
                stack.append(ch)
        return ''.join(stack)

